1	// Generated for you. All arena silhouettes and gameplay visuals start here.
2	import {
3	  BufferAttribute,
4	  BufferGeometry,
5	  CylinderGeometry,
6	  Group,
7	  type Material,
8	  Mesh,
9	  SphereGeometry,
10	} from "three";
11	
12	import type { ReturnTypeOfMaterials } from "./types.js";
13	
14	const roundedCache = new Map<string, BufferGeometry>();
15	
16	export type ShooterMaterials = ReturnTypeOfMaterials;
17	
18	function compactBox(width: number, height: number, depth: number): BufferGeometry {
19	  const halfX = width / 2;
20	  const halfY = height / 2;
21	  const halfZ = depth / 2;
22	  const positions = new Float32Array([
23	    -halfX,
24	    -halfY,
25	    -halfZ,
26	    halfX,
27	    -halfY,
28	    -halfZ,
29	    halfX,
30	    halfY,
31	    -halfZ,
32	    -halfX,
33	    halfY,
34	    -halfZ,
35	    -halfX,
36	    -halfY,
37	    halfZ,
38	    halfX,
39	    -halfY,
40	    halfZ,
41	    halfX,
42	    halfY,
43	    halfZ,
44	    -halfX,
45	    halfY,
46	    halfZ,
47	  ]);
48	  const normals = new Float32Array(positions.length);
49	  for (let index = 0; index < positions.length; index += 3) {
50	    const x = positions[index] ?? 0;
51	    const y = positions[index + 1] ?? 0;
52	    const z = positions[index + 2] ?? 0;
53	    const length = Math.hypot(x, y, z) || 1;
54	    normals[index] = x / length;
55	    normals[index + 1] = y / length;
56	    normals[index + 2] = z / length;
57	  }
58	  const geometry = new BufferGeometry();
59	  geometry.setAttribute("position", new BufferAttribute(positions, 3));
60	  geometry.setAttribute("normal", new BufferAttribute(normals, 3));
61	  geometry.setIndex([
62	    0, 1, 2, 0, 2, 3, 4, 6, 5, 4, 7, 6, 0, 4, 5, 0, 5, 1, 1, 5, 6, 1, 6, 2, 2, 6, 7, 2, 7, 3, 4, 0,
63	    3, 4, 3, 7,
64	  ]);
65	  return geometry;
66	}
67	
68	function roundedBox(
69	  width: number,
70	  height: number,
71	  depth: number,
72	  radius = 0.12,
73	  segments = 1,
74	): BufferGeometry {
75	  const key = `${width},${height},${depth},${radius},${segments}`;
76	  const cached = roundedCache.get(key);
77	  if (cached !== undefined) return cached;
78	  const geometry = compactBox(width, height, depth);
79	  roundedCache.set(key, geometry);
80	  return geometry;
81	}
82	
83	function shadowed(mesh: Mesh, cast = true): Mesh {
84	  mesh.castShadow = cast;
85	  mesh.receiveShadow = true;
86	  return mesh;
87	}
88	
89	function block(width: number, height: number, depth: number, material: Material): Mesh {
90	  return shadowed(new Mesh(roundedBox(width, height, depth), material));
91	}
92	
93	export function createArena(materials: ShooterMaterials) {
94	  const group = new Group();
95	  group.name = "arena";
96	  const floor = block(22, 0.4, 20, materials.arena);
97	  floor.name = "arena-floor";
98	  floor.position.set(0, -0.2, -2);
99	  group.add(floor);
100	  const walls = [
101	    { depth: 20, position: [-11, 1.7, -2] as const, width: 0.4 },
102	    { depth: 20, position: [11, 1.7, -2] as const, width: 0.4 },
103	    { depth: 0.4, position: [0, 1.7, -12] as const, width: 22 },
104	  ].map(({ depth, position, width }, index) => {
105	    const wall = block(width, 3.8, depth, materials.shadow);
106	    wall.name = `arena-wall-${index}`;
107	    wall.position.set(position[0], position[1], position[2]);
108	    group.add(wall);
109	    return wall;
110	  });
111	  for (let x = -9; x <= 9; x += 3) {
112	    const strip = new Mesh(compactBox(0.035, 0.012, 19), materials.trim);
113	    strip.position.set(x, 0.012, -2);
114	    strip.castShadow = false;
115	    strip.receiveShadow = false;
116	    group.add(strip);
117	  }
118	  for (let z = -11; z <= 7; z += 3) {
119	    const strip = new Mesh(compactBox(21, 0.012, 0.035), materials.trim);
120	    strip.position.set(0, 0.014, z);
121	    strip.castShadow = false;
122	    strip.receiveShadow = false;
123	    group.add(strip);
124	  }
125	  return { floor, group, walls };
126	}
127	
128	export function createPlayerVisual(materials: ShooterMaterials): Group {
129	  const group = new Group();
130	  group.name = "player-visual";
131	  const body = block(0.76, 1.35, 0.76, materials.player);
132	  body.position.y = 0.62;
133	  group.add(body);
134	  const visor = new Mesh(compactBox(0.56, 0.22, 0.08), materials.trim);
135	  visor.position.set(0, 0.88, -0.4);
136	  visor.castShadow = true;
137	  group.add(visor);
138	  const muzzle = new Mesh(
139	    new CylinderGeometry(0.08, 0.1, 0.5, 6).rotateX(Math.PI / 2),
140	    materials.shadow,
141	  );
142	  muzzle.position.set(0, 0.52, -0.55);
143	  muzzle.castShadow = true;
144	  group.add(muzzle);
145	  return group;
146	}
147	
148	export function createTargetVisual(materials: ShooterMaterials): Group {
149	  const group = new Group();
150	  group.name = "target-visual";
151	  const body = block(1.2, 1.8, 1, materials.hostile);
152	  body.position.y = 0.9;
153	  group.add(body);
154	  const ring = new Mesh(compactBox(1.4, 0.08, 0.08), materials.trim);
155	  ring.position.y = 0.9;
156	  ring.castShadow = true;
157	  group.add(ring);
158	  const crossbar = new Mesh(compactBox(0.08, 0.08, 1.4), materials.trim);
159	  crossbar.position.y = 0.9;
160	  crossbar.castShadow = true;
161	  group.add(crossbar);
162	  return group;
163	}
164	
165	export function createFriendlyVisual(materials: ShooterMaterials): Group {
166	  const group = new Group();
167	  const body = block(0.9, 1.4, 0.9, materials.player);
168	  body.position.y = 0.7;
169	  group.add(body);
170	  const antenna = new Mesh(new CylinderGeometry(0.04, 0.04, 0.5, 8), materials.trim);
171	  antenna.position.y = 1.65;
172	  group.add(antenna);
173	  return group;
174	}
175	
176	export function createWallVisual(materials: ShooterMaterials): Mesh {
177	  return block(0.65, 2.8, 2.8, materials.shadow);
178	}
179	
180	export function createPickupVisual(materials: ShooterMaterials): Group {
181	  const group = new Group();
182	  const base = block(0.65, 0.12, 0.65, materials.trim);
183	  base.position.y = 0.06;
184	  group.add(base);
185	  const orb = new Mesh(new SphereGeometry(0.25, 4, 3), materials.player);
186	  orb.position.y = 0.45;
