import type { ICtx, ScheduleHandle } from "@threenative/core";
import { CharacterBody3D, CollisionShape3D, type IPhysicsContext } from "@threenative/physics";
import { type Group, Vector3 } from "three";
import { directSpaceState } from "../physics.js";
import { createEnemyVisual } from "../render/shapes.js";
import type { GameState } from "../state.js";
import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER } from "./Player.js";

type GameCtx = ICtx<GameState, IPhysicsContext>;

const PATROL_SPEED = 2.5;
const CHASE_SPEED = 3.8;
const VISION_RANGE = 8;
const FIRE_COOLDOWN = 1.2;
const FIRE_RANGE = 12;

export class Enemy {
  readonly mesh: Group;
  readonly body: CharacterBody3D;
  readonly tags = ["hostile", "enemy"];
  health: number;
  alive = true;
  #onFire: (origin: Vector3) => void;
  #patrolPoints: Vector3[];
  #currentPatrolIndex = 0;
  #chasing = false;
  #playerLastSeenPos: Vector3 | undefined;
  #visionShape = CollisionShape3D.sphere(VISION_RANGE);
  #fireTimer = 0;
  #scanHandle: ScheduleHandle | undefined;

  constructor(
    ctx: GameCtx,
    materials: Parameters<typeof createEnemyVisual>[0],
    position: Vector3,
    patrolPoints: Vector3[],
    onFire: (origin: Vector3) => void = () => undefined,
  ) {
    this.#onFire = onFire;
    this.#patrolPoints = patrolPoints.length > 0 ? patrolPoints : [position];
    this.health = 60;
    this.mesh = createEnemyVisual(materials);
    this.mesh.position.copy(position);
    ctx.add(this.mesh);
    this.body = new CharacterBody3D({
      autostep: { maxHeight: 0.25, minWidth: 0.18 },
      collisionLayer: HOSTILE_LAYER,
      collisionMask: WORLD_LAYER | PLAYER_LAYER,
      object: this.mesh,
      physics: ctx.physics,
      shape: CollisionShape3D.capsule(0.35, 0.7),
    });
  }

  startVisionScanning(ctx: GameCtx, playerBodyId: number): void {
    const scan = (): void => {
      if (!this.alive) return;
      const hits = directSpaceState(ctx.physics).intersectShape({
        collisionMask: PLAYER_LAYER,
        maxResults: 4,
        position: this.mesh.position,
        shape: this.#visionShape,
      });
      const playerSeen = hits.some((hit) => hit.body.id === playerBodyId);
      if (playerSeen) {
        this.#chasing = true;
        this.#playerLastSeenPos = undefined;
      } else {
        this.#chasing = false;
      }
      this.#scanHandle = ctx.after(ctx.random.range(3, 8) / 60, scan);
    };
    this.#scanHandle = ctx.after(ctx.random.range(3, 8) / 60, scan);
  }

  update(ctx: GameCtx, playerPos: Vector3, dt: number): void {
    if (!this.alive) return;

    this.#fireTimer -= dt;

    if (this.#chasing) {
      this.#playerLastSeenPos = playerPos.clone();
      const direction = playerPos
        .clone()
        .sub(this.mesh.position)
        .normalize();
      this.body.velocity.x = direction.x * CHASE_SPEED;
      this.body.velocity.z = direction.z * CHASE_SPEED;

      const distToPlayer = this.mesh.position.distanceTo(playerPos);
      if (distToPlayer < FIRE_RANGE && this.#fireTimer <= 0) {
        this.#fireTimer = FIRE_COOLDOWN;
        this.#onFire(this.rifleOrigin());
      }
    } else {
      this.patrol();
    }

    this.body.moveAndSlide(dt);
  }

  private patrol(): void {
    if (this.#patrolPoints.length === 0) return;
    const targetPoint = this.#patrolPoints[this.#currentPatrolIndex];
    if (targetPoint === undefined) return;

    const direction = targetPoint
      .clone()
      .sub(this.mesh.position)
      .normalize();
    const distToTarget = this.mesh.position.distanceTo(targetPoint);

    if (distToTarget < 0.5) {
      this.#currentPatrolIndex =
        (this.#currentPatrolIndex + 1) % this.#patrolPoints.length;
    }

    this.body.velocity.x = direction.x * PATROL_SPEED;
    this.body.velocity.z = direction.z * PATROL_SPEED;
  }

  rifleOrigin(): Vector3 {
    return this.mesh.position
      .clone()
      .add(new Vector3(0.35, 0.9, -1.3));
  }

  takeDamage(amount: number): boolean {
    if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
    this.health = Math.max(0, this.health - amount);
    if (this.health > 0) return false;
    this.alive = false;
    this.mesh.visible = false;
    this.body.velocity.set(0, 0, 0);
    return true;
  }

  debug(): Record<string, unknown> {
    return {
      alive: this.alive,
      chasing: this.#chasing,
      health: this.health,
      position: this.mesh.position.toArray(),
    };
  }

  dispose(): void {
    this.#scanHandle?.cancel();
    this.body.dispose();
    this.mesh.removeFromParent();
  }
}

