export function createProjectileVisual(materials: ShooterMaterials): Mesh {
  return shadowed(new Mesh(new SphereGeometry(0.12, 4, 3), materials.trim), false);
}

export function createEnemyVisual(materials: ShooterMaterials): Group {
  const group = new Group();
  group.name = "enemy-visual";
  const body = block(0.7, 1.4, 0.7, materials.hostile);
  body.position.y = 0.7;
  group.add(body);
  const head = new Mesh(new SphereGeometry(0.28, 4, 3), materials.hostile);
  head.position.set(0, 1.32, 0);
  head.castShadow = true;
  group.add(head);
  const rifle = block(0.12, 0.65, 1.8, materials.trim);
  rifle.position.set(0.35, 0.8, -0.6);
  rifle.rotation.z = 0.2;
  group.add(rifle);
  const muzzle = new Mesh(
    new CylinderGeometry(0.06, 0.08, 0.35, 6).rotateX(Math.PI / 2),
    materials.shadow,
  );
  muzzle.position.set(0.35, 0.85, -1.35);
  muzzle.castShadow = true;
  group.add(muzzle);
  return group;
}

